//! Owner-private creation defaults. This is not attachment custody or unlink authority.
#![cfg(target_os = "linux")]
use std::{ffi::CString,fs::File,io::{self,Write},os::{fd::{AsRawFd,FromRawFd},unix::fs::MetadataExt},path::{Component,Path}};
fn invalid(s:&str)->io::Error{io::Error::new(io::ErrorKind::InvalidData,s)}
fn component(s:&str)->io::Result<CString>{if s.is_empty()||s=="."||s==".."||s.contains('/')||s.contains('\\'){return Err(invalid("Unsafe private storage component"));}CString::new(s).map_err(|_|invalid("NUL private storage component"))}
fn open(parent:&File,s:&str,flags:i32)->io::Result<File>{let s=component(s)?;
 // SAFETY: held directory FD, validated component, no-follow private creation mode.
 let fd=unsafe{libc::openat(parent.as_raw_fd(),s.as_ptr(),flags|libc::O_CLOEXEC|libc::O_NOFOLLOW,0o600)};if fd<0{return Err(io::Error::last_os_error());}
 // SAFETY: new descriptor ownership transferred once.
 Ok(unsafe{File::from_raw_fd(fd)})}
fn root(path:&Path)->io::Result<File>{let path=if path.is_absolute(){path.to_owned()}else{std::env::current_dir()?.join(path)};let mut f=File::open("/")?;for c in path.components(){match c{Component::RootDir=>(),Component::Normal(n)=>f=open(&f,n.to_str().ok_or_else(||invalid("NonUTF8 private root"))?,libc::O_RDONLY|libc::O_DIRECTORY)?,_=>return Err(invalid("Unsafe private root"))}}let m=f.metadata()?;
 // SAFETY: geteuid has no pointer arguments.
 if m.uid()!=unsafe{libc::geteuid()}||m.mode()&0o7777!=0o700{return Err(invalid("Existing storage root is unsafe; retained without chmod"));}Ok(f)}
fn directory(parent:&File,s:&str)->io::Result<File>{let f=match open(parent,s,libc::O_RDONLY|libc::O_DIRECTORY){Ok(f)=>f,Err(e)if e.kind()==io::ErrorKind::NotFound=>{let c=component(s)?;
 // SAFETY: held parent, validated component; never chmod an existing directory.
 if unsafe{libc::mkdirat(parent.as_raw_fd(),c.as_ptr(),0o700)}<0{return Err(io::Error::last_os_error());}parent.sync_all()?;open(parent,s,libc::O_RDONLY|libc::O_DIRECTORY)?},Err(e)=>return Err(e)};let m=f.metadata()?;let p=parent.metadata()?;if m.uid()!=p.uid()||m.gid()!=p.gid()||m.mode()&0o7777!=0o700{return Err(invalid("Existing space directory is unsafe; retained without chmod"));}Ok(f)}
fn space(path:&Path,slug:&str)->io::Result<File>{let r=root(path)?;let spaces=directory(&r,"spaces")?;directory(&spaces,slug)}
/// Marker presence selects normal-initialized strict defaults; it grants no custody.
pub(crate) fn is_designated(path:&Path)->io::Result<bool>{match std::fs::symlink_metadata(path.join(super::data_root_designation::NAME)){Ok(_)=>Ok(true),Err(e)if e.kind()==io::ErrorKind::NotFound=>Ok(false),Err(e)=>Err(e)}}
pub(crate) struct SqliteFile{path:std::path::PathBuf,root:File,file:File,identity:(u64,u64)}
impl SqliteFile{pub(crate) fn fence(&self)->io::Result<()>{let fresh=root(&self.path)?;let a=fresh.metadata()?;let b=self.root.metadata()?;if (a.dev(),a.ino())!=(b.dev(),b.ino()){return Err(invalid("SQLite root replaced during initialization"));}let current=open(&fresh,"starlane-notes.db",libc::O_RDONLY|libc::O_NONBLOCK)?;let m=current.metadata()?;let held=self.file.metadata()?;if (m.dev(),m.ino())!=self.identity||(held.dev(),held.ino())!=self.identity||m.nlink()!=1||m.mode()&0o7777!=0o600||m.uid()!=a.uid()||m.gid()!=a.gid(){return Err(invalid("SQLite designation changed during initialization"));}Ok(())}}
pub(crate) fn prepare_sqlite(path:&Path)->io::Result<Option<SqliteFile>>{if !is_designated(path)?{return Ok(None);}let r=root(path)?;let f=match open(&r,"starlane-notes.db",libc::O_RDWR|libc::O_CREAT|libc::O_EXCL){Ok(f)=>{f.sync_all()?;r.sync_all()?;f},Err(e)if e.kind()==io::ErrorKind::AlreadyExists=>open(&r,"starlane-notes.db",libc::O_RDWR|libc::O_NONBLOCK)?,Err(e)=>return Err(e)};let m=f.metadata()?;let o=r.metadata()?;if !m.is_file()||m.nlink()!=1||m.mode()&0o7777!=0o600||m.uid()!=o.uid()||m.gid()!=o.gid(){return Err(invalid("Existing SQLite file is unsafe; retained without chmod or truncation"));}let v=SqliteFile{path:path.to_owned(),root:r,file:f,identity:(m.dev(),m.ino())};v.fence()?;Ok(Some(v))}
pub(crate) fn initialize(path:&Path,slug:&str)->io::Result<()>{let s=space(path,slug)?;for name in ["docs","attachments","excalidraw","drafts","archived","trashed"]{directory(&s,name)?;}let controls=directory(&s,".starlane")?;directory(&controls,"templates")?;Ok(())}
pub(crate) fn write(path:&Path,slug:&str,category:&str,filename:&str,bytes:&[u8])->io::Result<()>{if !matches!(category,"docs"|"drafts"|"archived"|"trashed"){return Err(invalid("Invalid private document category"));}let s=space(path,slug)?;let d=directory(&s,category)?;let mut f=match open(&d,filename,libc::O_WRONLY|libc::O_CREAT|libc::O_EXCL){Ok(f)=>f,Err(e)if e.kind()==io::ErrorKind::AlreadyExists=>open(&d,filename,libc::O_WRONLY|libc::O_NONBLOCK)?,Err(e)=>return Err(e)};let m=f.metadata()?;let owner=d.metadata()?;if !m.is_file()||m.nlink()!=1||m.uid()!=owner.uid()||m.gid()!=owner.gid()||m.mode()&0o7777!=0o600{return Err(invalid("Existing document file is unsafe; retained without chmod or truncation"));}let current=open(&d,filename,libc::O_RDONLY|libc::O_NONBLOCK)?.metadata()?;if (current.dev(),current.ino())!=(m.dev(),m.ino()){return Err(invalid("Document path replaced before write"));}f.set_len(0)?;f.write_all(bytes)?;f.sync_all()?;d.sync_all()}
#[cfg(test)]mod tests{use super::*;use std::os::unix::fs::{PermissionsExt,symlink};static ID:std::sync::atomic::AtomicU64=std::sync::atomic::AtomicU64::new(0);fn fixture()->std::path::PathBuf{let p=std::env::temp_dir().join(format!("private-space-{}-{}",std::process::id(),ID.fetch_add(1,std::sync::atomic::Ordering::Relaxed)));std::fs::create_dir(&p).unwrap();std::fs::set_permissions(&p,std::fs::Permissions::from_mode(0o700)).unwrap();p}
#[test]fn new_layout_and_files_private(){let p=fixture();initialize(&p,"slug").unwrap();write(&p,"slug","docs","page.md",b"body").unwrap();write(&p,"slug","drafts","draft.md",b"draft").unwrap();for d in ["spaces","spaces/slug","spaces/slug/docs","spaces/slug/.starlane/templates"]{assert_eq!(std::fs::metadata(p.join(d)).unwrap().mode()&0o777,0o700);}assert_eq!(std::fs::metadata(p.join("spaces/slug/docs/page.md")).unwrap().mode()&0o777,0o600);}
#[test]fn existing_unsafe_directory_unchanged(){let p=fixture();initialize(&p,"slug").unwrap();let d=p.join("spaces/slug/docs");std::fs::set_permissions(&d,std::fs::Permissions::from_mode(0o755)).unwrap();assert!(initialize(&p,"slug").is_err());assert_eq!(std::fs::metadata(&d).unwrap().mode()&0o777,0o755);}
#[test]fn borrowed_directory_and_file_retained(){let p=fixture();initialize(&p,"slug").unwrap();let foreign=p.join("foreign");std::fs::write(&foreign,b"FOREIGN").unwrap();symlink(&foreign,p.join("spaces/slug/docs/link.md")).unwrap();assert!(write(&p,"slug","docs","link.md",b"BAD").is_err());assert_eq!(std::fs::read(&foreign).unwrap(),b"FOREIGN");let bad=p.join("spaces/slug/docs/bad.md");std::fs::write(&bad,b"OLD").unwrap();std::fs::set_permissions(&bad,std::fs::Permissions::from_mode(0o644)).unwrap();assert!(write(&p,"slug","docs","bad.md",b"BAD").is_err());assert_eq!(std::fs::read(bad).unwrap(),b"OLD");}
#[test]fn aliased_existing_file_never_truncated(){let p=fixture();initialize(&p,"slug").unwrap();write(&p,"slug","docs","page.md",b"OLD").unwrap();std::fs::hard_link(p.join("spaces/slug/docs/page.md"),p.join("alias")).unwrap();assert!(write(&p,"slug","docs","page.md",b"BAD").is_err());assert_eq!(std::fs::read(p.join("alias")).unwrap(),b"OLD");}
#[test]fn exact_existing_private_file_updates(){let p=fixture();initialize(&p,"slug").unwrap();write(&p,"slug","docs","page.md",b"LONG OLD").unwrap();write(&p,"slug","docs","page.md",b"NEW").unwrap();assert_eq!(std::fs::read(p.join("spaces/slug/docs/page.md")).unwrap(),b"NEW");}
}

#[cfg(test)]mod sqlite_tests{use super::*;use std::os::unix::fs::{PermissionsExt,symlink};static ID:std::sync::atomic::AtomicU64=std::sync::atomic::AtomicU64::new(0);fn fixture()->std::path::PathBuf{let p=std::env::temp_dir().join(format!("private-sqlite-{}-{}",std::process::id(),ID.fetch_add(1,std::sync::atomic::Ordering::Relaxed)));super::super::data_root_designation::initialize(&p).unwrap();p}
#[test]fn new_sqlite_private_and_restart_preserves_inode(){let p=fixture();let held=prepare_sqlite(&p).unwrap().unwrap();held.fence().unwrap();let before=std::fs::metadata(p.join("starlane-notes.db")).unwrap();assert_eq!(before.mode()&0o777,0o600);drop(held);let held=prepare_sqlite(&p).unwrap().unwrap();held.fence().unwrap();assert_eq!(std::fs::metadata(p.join("starlane-notes.db")).unwrap().ino(),before.ino());}
#[test]fn borrowed_unsafe_and_aliased_db_retained(){let p=fixture();let db=p.join("starlane-notes.db");std::fs::write(&db,b"KEEP").unwrap();std::fs::set_permissions(&db,std::fs::Permissions::from_mode(0o644)).unwrap();assert!(prepare_sqlite(&p).is_err());assert_eq!(std::fs::read(&db).unwrap(),b"KEEP");std::fs::remove_file(&db).unwrap();let foreign=p.join("foreign");std::fs::write(&foreign,b"BORROWED").unwrap();symlink(&foreign,&db).unwrap();assert!(prepare_sqlite(&p).is_err());assert_eq!(std::fs::read(&foreign).unwrap(),b"BORROWED");std::fs::remove_file(&db).unwrap();let held=prepare_sqlite(&p).unwrap().unwrap();std::fs::hard_link(&db,p.join("alias")).unwrap();assert!(held.fence().is_err());assert!(prepare_sqlite(&p).is_err());}
#[test]fn markerless_legacy_does_not_create_database(){let p=std::env::temp_dir().join(format!("private-markerless-{}",std::process::id()));let _=std::fs::create_dir(&p);assert!(prepare_sqlite(&p).unwrap().is_none());assert!(!p.join("starlane-notes.db").exists());}
}
